package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.resonance.*;import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.*;import net.minecraft.core.particles.*;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;
/** Everything fits inside the column: mouths orbit at radius .39, item radius .29. */
public final class ResonanceRenderer implements BlockEntityRenderer<ResonanceEntity>{
 private final BlockEntityRendererProvider.Context context;public ResonanceRenderer(BlockEntityRendererProvider.Context c){context=c;}
 public void render(ResonanceEntity d,float partial,PoseStack p,MultiBufferSource buf,int light,int overlay){if(d.getLevel()==null)return;float t=d.getLevel().getGameTime()+partial;float ramp=d.active()&&!d.paused?Math.min(1,d.elapsed/30f)*Math.min(1,(d.total-d.elapsed)/30f):0;float angle=(d.spin+d.spinSpeed*partial)*180f/(float)Math.PI;for(int i=0;i<9;i++){var item=d.inventory.getItem(i);if(item.isEmpty())continue;double a=(i-1)*Math.PI/4;float xx=i==0?.5f:.5f+(float)Math.sin(a)*.29f,zz=i==0?.5f:.5f-(float)Math.cos(a)*.29f;p.pushPose();p.translate(xx,1.005+Math.sin(t*.05+i)*.012,zz);p.mulPose(Axis.YP.rotationDegrees(t*.5f));float dissolve=1;if(d.active()&&i>0&&!d.paused){int ordinal=0;for(int k=1;k<i;k++)if(!d.echoes.get(k).isEmpty())ordinal++;float progress=Math.clamp((d.elapsed+partial-ordinal*100)/100f,0,1);dissolve=1-.7f*progress;}p.scale(.23f*dissolve,.23f*dissolve,.23f*dissolve);Minecraft.getInstance().getItemRenderer().renderStatic(item,ItemDisplayContext.FIXED,light,overlay,p,buf,d.getLevel(),i);p.popPose();}
 for(int i=0;i<8;i++){float a=(angle+i*45)*(float)Math.PI/180;float x=.5f+(float)Math.sin(a)*.39f,z=.5f-(float)Math.cos(a)*.39f;p.pushPose();p.translate(x,1.07+Math.sin(t*.07+i)*.016,z);p.mulPose(Axis.YP.rotationDegrees(-angle-i*45));p.mulPose(Axis.XP.rotationDegrees(90));p.scale(.13f,.13f,.13f);p.translate(-.5,-.5,-.5);context.getBlockRenderDispatcher().renderSingleBlock(Blocks.HOPPER.defaultBlockState(),p,buf,light,overlay);p.popPose();}
 // Each tiny fragment follows an inward arc, rather than a random outward explosion.
 if(d.active()&&!d.paused){var ir=Minecraft.getInstance().getItemRenderer();for(int slot=1;slot<9;slot++){var sample=d.echoes.get(slot);if(sample.isEmpty())continue;int ordinal=0;for(int k=1;k<slot;k++)if(!d.echoes.get(k).isEmpty())ordinal++;float phase=(d.elapsed+partial-ordinal*100)/100f;if(phase<0||phase>1.15)continue;double a=(slot-1)*Math.PI/4;for(int f=0;f<9;f++){float travel=(t*.036f+f*.11f)%1;p.pushPose();p.translate(.5+Math.sin(a)*.29*(1-travel),1.01+Math.sin(travel*Math.PI)*.06,.5-Math.cos(a)*.29*(1-travel));p.mulPose(Axis.YP.rotationDegrees(t*7+f*39));p.scale(.022f,.022f,.022f);ir.renderStatic(sample,ItemDisplayContext.FIXED,light,overlay,p,buf,d.getLevel(),f);p.popPose();}}}
 if(d.active()&&!d.paused){var v=buf.getBuffer(RenderType.lines());var pose=p.last();for(int h=0;h<8;h++)for(int w=0;w<3;w++){double a=(angle+h*45)*Math.PI/180;float f=(t*.045f+w/3f)%1,dist=.35f*(1-f),radius=.02f+.035f*f;for(int j=0;j<16;j++){double a1=j*Math.PI/8,a2=(j+1)*Math.PI/8;float x1=.5f+(float)Math.sin(a)*dist+(float)Math.cos(a)*radius*(float)Math.cos(a1),z1=.5f-(float)Math.cos(a)*dist+(float)Math.sin(a)*radius*(float)Math.cos(a1),y1=1.06f+radius*(float)Math.sin(a1);float x2=.5f+(float)Math.sin(a)*dist+(float)Math.cos(a)*radius*(float)Math.cos(a2),z2=.5f-(float)Math.cos(a)*dist+(float)Math.sin(a)*radius*(float)Math.cos(a2),y2=1.06f+radius*(float)Math.sin(a2);float dx=x2-x1,dy=y2-y1,dz=z2-z1,len=(float)Math.sqrt(dx*dx+dy*dy+dz*dz);v.addVertex(pose,x1,y1,z1).setColor(.45f,.9f,.87f,1-f).setNormal(pose,dx/len,dy/len,dz/len);v.addVertex(pose,x2,y2,z2).setColor(.45f,.9f,.87f,1-f).setNormal(pose,dx/len,dy/len,dz/len);}}}
 }
}
